{{ config(materialized='view') }}

SELECT
  b.retail_year,
  b.period,
  st.store_key,
  st.store_id,
  st.store_name,
  st.region,
  st.store_format,
  b.sales_lines,
  b.units_sold,
  b.transactions,
  b.gross_sales,
  b.discount_value,
  b.sales_revenue,
  b.returns_value,
  b.net_revenue,
  b.cogs,
  b.gross_margin,
  b.promo_sales_revenue,
  b.target_net_revenue,
  CAST(b.sales_revenue AS DOUBLE) / NULLIF(CAST(b.transactions AS DOUBLE), 0) AS aov,
  CAST(b.units_sold AS DOUBLE) / NULLIF(CAST(b.transactions AS DOUBLE), 0) AS upt,
  CAST(b.sales_revenue AS DOUBLE) / NULLIF(CAST(b.units_sold AS DOUBLE), 0) AS asp,
  CAST(b.gross_margin AS DOUBLE) / NULLIF(CAST(b.net_revenue AS DOUBLE), 0) AS gross_margin_pct,
  CAST(b.returns_value AS DOUBLE) / NULLIF(CAST(b.sales_revenue AS DOUBLE), 0) AS return_rate_value,
  CAST(b.promo_sales_revenue AS DOUBLE) / NULLIF(CAST(b.sales_revenue AS DOUBLE), 0) AS promo_revenue_share,
  CAST(b.net_revenue AS DOUBLE) / NULLIF(CAST(b.target_net_revenue AS DOUBLE), 0) AS target_achievement_pct
FROM (
  SELECT
    x.retail_year,
    x.period,
    x.store_key,
    SUM(x.sales_lines) AS sales_lines,
    SUM(x.units_sold) AS units_sold,
    SUM(x.transactions) AS transactions,
    SUM(x.gross_sales) AS gross_sales,
    SUM(x.discount_value) AS discount_value,
    SUM(x.sales_revenue) AS sales_revenue,
    SUM(x.returns_value) AS returns_value,
    SUM(x.net_revenue) AS net_revenue,
    SUM(x.cogs) AS cogs,
    SUM(x.gross_margin) AS gross_margin,
    SUM(x.promo_sales_revenue) AS promo_sales_revenue,
    SUM(x.target_net_revenue) AS target_net_revenue
  FROM (
    SELECT
      w.retail_year,
      w.retail_half AS period,
      w.store_key,
      w.sales_lines,
      w.units_sold,
      w.transactions,
      w.gross_sales,
      w.discount_value,
      w.sales_revenue,
      w.returns_value,
      w.net_revenue,
      w.cogs,
      w.gross_margin,
      w.promo_sales_revenue,
      w.target_net_revenue
    FROM {{ ref('v_performance_store_week') }} AS w
    UNION ALL
    SELECT
      w.retail_year,
      N'FY',
      w.store_key,
      w.sales_lines,
      w.units_sold,
      w.transactions,
      w.gross_sales,
      w.discount_value,
      w.sales_revenue,
      w.returns_value,
      w.net_revenue,
      w.cogs,
      w.gross_margin,
      w.promo_sales_revenue,
      w.target_net_revenue
    FROM {{ ref('v_performance_store_week') }} AS w
  ) AS x
  GROUP BY
    x.retail_year,
    x.period,
    x.store_key
) AS b
JOIN {{ ref('dim_store') }} AS st
  ON st.store_key = b.store_key
